<?php
namespace PharmaSure\Integrations\Services;
final class CredentialVault{private function key(){if(!defined('AUTH_KEY')||strlen(AUTH_KEY)<32){return new \WP_Error('encryption_key_unavailable','A strong WordPress AUTH_KEY is required.',array('status'=>503));}return hash('sha256',AUTH_KEY,true);}public function encrypt(array $value){$key=$this->key();if(is_wp_error($key)){return $key;}$plain=wp_json_encode($value);if(function_exists('sodium_crypto_secretbox')){$nonce=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);return 's1:'.base64_encode($nonce.sodium_crypto_secretbox($plain,$nonce,$key));}$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);return false===$cipher?new \WP_Error('encryption_failed','Credentials could not be encrypted.'):'o1:'.base64_encode($iv.$tag.$cipher);}public function decrypt($stored){$key=$this->key();if(is_wp_error($key)){return $key;}$raw=base64_decode(substr((string)$stored,3),true);if(false===$raw){return new \WP_Error('credential_corrupt','Encrypted credentials are invalid.');}if(str_starts_with($stored,'s1:')){$nonce=substr($raw,0,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);$plain=sodium_crypto_secretbox_open(substr($raw,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),$nonce,$key);}else{$iv=substr($raw,0,12);$tag=substr($raw,12,16);$plain=openssl_decrypt(substr($raw,28),'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);}if(false===$plain){return new \WP_Error('credential_decryption_failed','Credentials could not be decrypted.');}$data=json_decode($plain,true);return is_array($data)?$data:new \WP_Error('credential_corrupt','Credential payload is invalid.');}}
